/**
 * ScrollForMoreHint — viewport-anchored pill signaling there's more below.
 *
 * Bobs gently. Fades out as soon as the user starts scrolling.
 * Only shown when the form content actually overflows the viewport.
 */

import { useEffect } from 'react';
import { Pressable, StyleSheet, Text } from 'react-native';
import Animated, {
  Easing,
  Extrapolation,
  interpolate,
  useAnimatedStyle,
  useDerivedValue,
  useSharedValue,
  withRepeat,
  withSequence,
  withTiming,
  type SharedValue,
} from 'react-native-reanimated';
import { ChevronDown } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import { useThemeColors } from '@/theme/ThemeContext';
import { fontWeights, typography } from '@/theme/typography';
import { useReduceMotion } from '@/hooks/useReduceMotion';

interface ScrollForMoreHintProps {
  scrollY: SharedValue<number>;
  visible: SharedValue<number>;
  onPress: () => void;
}

const FADE_DISTANCE = 24;
const BOB_AMPLITUDE = 3;

export function ScrollForMoreHint({
  scrollY,
  visible,
  onPress,
}: ScrollForMoreHintProps) {
  const { colors } = useThemeColors();
  const reduceMotion = useReduceMotion();
  const bob = useSharedValue(0);

  useEffect(() => {
    if (reduceMotion) {
      bob.value = 0;
      return;
    }
    bob.value = withRepeat(
      withSequence(
        withTiming(1, { duration: 800, easing: Easing.inOut(Easing.quad) }),
        withTiming(0, { duration: 800, easing: Easing.inOut(Easing.quad) })
      ),
      -1,
      false
    );
  }, [reduceMotion, bob]);

  const wrapStyle = useAnimatedStyle(() => {
    const scrollFade = interpolate(
      scrollY.value,
      [0, FADE_DISTANCE],
      [1, 0],
      Extrapolation.CLAMP
    );
    return {
      opacity: scrollFade * visible.value,
      transform: [
        { translateY: interpolate(bob.value, [0, 1], [0, -BOB_AMPLITUDE]) },
      ],
    };
  });

  const chevronStyle = useAnimatedStyle(() => ({
    transform: [
      { translateY: interpolate(bob.value, [0, 1], [0, BOB_AMPLITUDE]) },
    ],
  }));

  const handlePress = () => {
    void Haptics.selectionAsync();
    onPress();
  };

  return (
    <Animated.View
      pointerEvents='box-none'
      style={[styles.wrap, wrapStyle]}
    >
      <Pressable
        accessibilityHint='Scrolls down to reveal more habit options'
        accessibilityLabel='More options below'
        accessibilityRole='button'
        style={({ pressed }) => [
          styles.pill,
          {
            backgroundColor: colors.card,
            borderColor: colors.border,
            opacity: pressed ? 0.85 : 1,
          },
        ]}
        onPress={handlePress}
      >
        <Animated.View style={chevronStyle}>
          <ChevronDown
            color={colors.text.secondary}
            size={14}
            strokeWidth={2.5}
          />
        </Animated.View>
        <Text
          style={{
            ...typography.caption,
            fontWeight: fontWeights.semibold,
            color: colors.text.secondary,
          }}
        >
          Scroll for more
        </Text>
      </Pressable>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  pill: {
    alignItems: 'center',
    borderRadius: 9999,
    borderWidth: 1,
    elevation: 4,
    flexDirection: 'row',
    gap: 6,
    paddingHorizontal: 12,
    paddingVertical: 8,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.08,
    shadowRadius: 12,
  },
  wrap: {
