interface ScrollForMoreHintProps {
  scrollY: SharedValue<number>;
  viewportHeight: SharedValue<number>;
  anchorY: SharedValue<number>;
}

export function ScrollForMoreHint({
  scrollY,
  viewportHeight,
  anchorY,
}: ScrollForMoreHintProps) {
  const { colors } = useThemeColors();
  const reduceMotion = useReduceMotion();
  const bob = useSharedValue(0);

  useEffect(() => {
    if (reduceMotion) return;
    bob.value = withRepeat(
      withSequence(
        withTiming(1, { duration: 900, easing: Easing.inOut(Easing.quad) }),
        withTiming(0, { duration: 900, easing: Easing.inOut(Easing.quad) })
      ),
      -1,
      false
    );
  }, [reduceMotion, bob]);

  const wrapStyle = useAnimatedStyle(() => {
    if (anchorY.value <= 0 || viewportHeight.value <= 0) return { opacity: 0 };
    const distance = anchorY.value - (scrollY.value + viewportHeight.value);
    const visible = interpolate(
      distance,
      [-32, 0],
      [0, 1],
      Extrapolation.CLAMP
    );
    const bobOpacity = interpolate(bob.value, [0, 1], [0.35, 0.7]);
    return {
      opacity: visible * bobOpacity,
      transform: [{ translateY: interpolate(bob.value, [0, 1], [0, 3]) }],
    };
  });

  return (
    <Animated.View style={[styles.wrap, wrapStyle]}>
      <ChevronDown
        color={colors.text.tertiary}
        size={18}
        strokeWidth={2}
      />
    </Animated.View>
  );
}

